import React from 'react';
import { motion } from 'framer-motion';
import { CalendarToday, Queue, MedicalServices, Security } from '@mui/icons-material';

const features = [
  {
    icon: <CalendarToday />,
    title: 'Online Appointment Booking',
    description: 'Schedule appointments with doctors at your convenience through our intuitive booking system.'
  },
  {
    icon: <Queue />,
    title: 'Live Queue Tracking',
    description: 'Monitor your position in the queue in real-time and get notified when it\'s your turn.'
  },
  {
    icon: <MedicalServices />,
    title: 'Digital Medical Records',
    description: 'Access your complete medical history securely from anywhere, anytime.'
  },
  {
    icon: <Security />,
    title: 'Secure Certificate System',
    description: 'Generate and manage medical certificates with blockchain-level security.'
  }
];

const Features = () => {
  return (
    <section className="py-20 bg-slate-950 text-white">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <motion.div
          className="text-center mb-16"
          initial={{ opacity: 0, y: 50 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          viewport={{ once: true }}
        >
          <h2 className="text-4xl font-black text-cyan-200 mb-4">Key Features</h2>
          <p className="text-lg text-cyan-100/75 max-w-2xl mx-auto">
            Everything you need for seamless healthcare management
          </p>
        </motion.div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
          {features.map((feature, index) => (
            <motion.div
              key={index}
              className="bg-white/10 p-8 rounded-2xl shadow-[0_20px_40px_rgba(0,0,0,0.35)] hover:shadow-[0_25px_65px_rgba(99,102,241,0.35)] transition-all duration-300 hover:-translate-y-3 border border-cyan-300/40 backdrop-blur-xl text-center"
              initial={{ opacity: 0, y: 50 }}
              whileInView={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.6, delay: index * 0.08 }}
              viewport={{ once: true }}
              whileHover={{ y: -12 }}
            >
              <div className="w-20 h-20 bg-gradient-to-br from-blue-400 to-purple-600 rounded-full flex items-center justify-center mx-auto mb-6 text-white text-3xl">
                {feature.icon}
              </div>
              <h3 className="text-xl font-semibold text-slate-800 mb-4">{feature.title}</h3>
              <p className="text-slate-600 leading-relaxed">{feature.description}</p>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Features;
